CREATE TABLE `CL_CallAssetAllocation` (
  `id` int NOT NULL AUTO_INCREMENT,
  `call_id` varchar(45) DEFAULT NULL,
  `assetid` varchar(45) DEFAULT NULL,
  `serialnumber` varchar(100) DEFAULT NULL,
  `user_id` varchar(45) DEFAULT NULL,
  `username` varchar(100) DEFAULT NULL,
  `mode` varchar(100) DEFAULT NULL,
  `DependingAssetId` varchar(45) DEFAULT NULL,
  `createdBy` varchar(45) DEFAULT NULL,
  `createdById` int DEFAULT NULL,
  `createdOn` datetime DEFAULT NULL,
  `loc_id` varchar(45) DEFAULT NULL,
  `location` varchar(45) DEFAULT NULL,
  `assettype` varchar(45) DEFAULT NULL,
  `status` varchar(45) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=165 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

