DROP TABLE IF EXISTS `CL_CallLogSla`;

CREATE TABLE `CL_CallLogSla` (
  `id` int NOT NULL AUTO_INCREMENT,
  `call_id` varchar(45) DEFAULT NULL,
  `calllog_time` datetime DEFAULT NULL,
  `support_type` varchar(45) DEFAULT NULL,
  `response_time` datetime DEFAULT NULL,
  `resolution_time` datetime DEFAULT NULL,
  `response_status` varchar(45) DEFAULT NULL,
  `resolution_status` varchar(45) DEFAULT NULL,
  `alert_type` varchar(45) DEFAULT NULL,
  `l1_mail` varchar(75) DEFAULT NULL,
  `l1_time` datetime DEFAULT NULL,
  `l1_status` varchar(45) DEFAULT NULL,
  `l1r_time` datetime DEFAULT NULL,
  `l1r_status` varchar(45) DEFAULT NULL,
  `l2_mail` varchar(75) DEFAULT NULL,
  `l2_time` datetime DEFAULT NULL,
  `l2_status` varchar(45) DEFAULT NULL,
  `l2r_time` datetime DEFAULT NULL,
  `l2r_status` varchar(45) DEFAULT NULL,
  `l3_mail` varchar(75) DEFAULT NULL,
  `l3_time` datetime DEFAULT NULL,
  `l3_status` varchar(45) DEFAULT NULL,
  `l3r_time` datetime DEFAULT NULL,
  `l3r_status` varchar(45) DEFAULT NULL,
  `l4_mail` varchar(75) DEFAULT NULL,
  `l4_time` datetime DEFAULT NULL,
  `l4_status` varchar(45) DEFAULT NULL,
  `l4r_time` datetime DEFAULT NULL,
  `l4r_status` varchar(45) DEFAULT NULL,
  `sla_pause` varchar(45) DEFAULT NULL,
  `pause_reason` varchar(2000) DEFAULT NULL,
  `resume_reason` varchar(2000) DEFAULT NULL,
  `sla_pend` varchar(45) DEFAULT NULL,
  `sla_parked_at` datetime DEFAULT NULL,
  `sla_pendtime` time DEFAULT NULL,
  `call_status` varchar(45) DEFAULT NULL,
  `ack_status` varchar(45) DEFAULT NULL,
  `createdBy` varchar(45) DEFAULT NULL,
  `createdById` varchar(45) DEFAULT NULL,
  `createdOn` datetime DEFAULT NULL,
  `updatedBy` varchar(45) DEFAULT NULL,
  `updatedById` varchar(45) DEFAULT NULL,
  `updatedOn` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

